package com.aistock.prediction.question;
import com.aistock.common.BusinessException;import com.aistock.prediction.explanation.ExplanationTemplate;import com.fasterxml.jackson.databind.*;import org.springframework.http.HttpStatus;import java.util.*;
public final class QuestionAnswerTemplate {
 public record Answer(String status,String topic,JsonNode paragraphs){}
 private QuestionAnswerTemplate(){}
 public static Answer render(JsonNode raw,Map<String,String> facts,ObjectMapper m){if(raw==null||!raw.isObject()||raw.size()!=3||!raw.path("status").isTextual()||!raw.path("topic").isTextual()||!raw.path("paragraphs").isArray())throw invalid();String status=raw.path("status").asText(),topic=raw.path("topic").asText();if(!Set.of("ANSWERED","OUT_OF_SCOPE").contains(status)||!Set.of("INDICATOR","PREDICTION","VERIFICATION","RISK","LIMITATION").contains(topic))throw invalid();if(status.equals("OUT_OF_SCOPE")){if(!topic.equals("LIMITATION")||!raw.path("paragraphs").isEmpty())throw invalid();return new Answer(status,topic,m.createArrayNode());}if(Set.of("PREDICTION","VERIFICATION").contains(topic)&&!facts.containsKey("PRED_ORIGIN_DATE"))throw invalid();var wrapped=m.createObjectNode();wrapped.set("paragraphs",raw.path("paragraphs"));var paragraphs=ExplanationTemplate.render(wrapped,facts,m);var refs=new HashSet<String>();for(var p:raw.path("paragraphs")){String plain=p.path("template").asText().replaceAll("\\{\\{[A-Z][A-Z0-9_]{0,31}\\}\\}","");if(java.util.regex.Pattern.compile("金叉|死叉|突破|跌破|穿越|实时|即时").matcher(plain).find())throw invalid();p.path("refs").forEach(r->refs.add(r.asText()));}if(!refs.containsAll(Set.of("AS_OF","BASIS_LIMIT","FRESHNESS_LIMIT")))throw invalid();if(topic.equals("INDICATOR")&&!((refs.contains("QA_MA_DEF")&&!Collections.disjoint(refs,Set.of("MA5_STATE","MA10_STATE","MA20_STATE")))||(refs.contains("QA_MACD_DEF")&&refs.contains("MACD_STATE"))||(refs.contains("QA_RSI_DEF")&&refs.contains("RSI_STATE"))))throw invalid();if(topic.equals("PREDICTION")&&!refs.containsAll(Set.of("PRED_ORIGIN_DATE","PRED_TREND","PRED_RELATIVE_ORIGIN","PRED_LIMIT")))throw invalid();if(topic.equals("VERIFICATION")&&!refs.containsAll(Set.of("PRED_VERIFICATION","PRED_LIMIT")))throw invalid();if(refs.stream().anyMatch(k->k.startsWith("PRED_"))&&!refs.containsAll(Set.of("PRED_ORIGIN_DATE","PRED_VERIFICATION","PRED_LIMIT","PRED_CONTEXT_RELATION")))throw invalid();for(int i=1;i<=5;i++)if(refs.contains("PRED_P"+i)&&!refs.contains("PRED_D"+i))throw invalid();return new Answer(status,topic,paragraphs);}
 private static BusinessException invalid(){return new BusinessException("AI_OUTPUT_INVALID","回答未通过依据核验，原分析保留",HttpStatus.UNPROCESSABLE_ENTITY);}
}
